SET @p := (SELECT project_id FROM migration_project WHERE name='바사증권 트레이딩 시스템');
DELETE FROM dependency WHERE project_id=@p;
DELETE FROM certificate WHERE project_id=@p;
DELETE bp FROM backup_plan bp JOIN asset a ON a.asset_id=bp.asset_id WHERE a.project_id=@p;
DELETE i FROM asset_ip i JOIN asset a ON a.asset_id=i.asset_id WHERE a.project_id=@p;
DELETE s FROM asset_software s JOIN asset a ON a.asset_id=s.asset_id WHERE a.project_id=@p;
DELETE FROM asset WHERE project_id=@p;

